import{_ as t,o as a,c as s,j as e,a as r}from"./chunks/framework.QCr1ZR1X.js";const p=JSON.parse('{"title":"思维导图-第7章-工业大数据","description":"","frontmatter":{},"headers":[],"relativePath":"mindmap/思维导图-第7章-工业大数据.md","filePath":"mindmap/思维导图-第7章-工业大数据.md","lastUpdated":1786967935000}'),i={name:"mindmap/思维导图-第7章-工业大数据.md"};function d(n,o,c,m,_,l){return a(),s("div",null,[...o[0]||(o[0]=[e("h1",{id:"思维导图-第7章-工业大数据",tabindex:"-1"},[r("思维导图-第7章-工业大数据 "),e("a",{class:"header-anchor",href:"#思维导图-第7章-工业大数据","aria-label":'Permalink to "思维导图-第7章-工业大数据"'},"​")],-1),e("div",{class:"mermaid"},'# 第7章 工业大数据 — 思维导图 ## 7.1 从"老师傅的手感"到"数据的判断" ### 张师傅反应釜故事 - 靠"手感"摸温度 - 靠"听音"辨异常 - 数据化的转变：传感器代替经验 ### 工业大数据的4V特点 - Volume（海量） - 单台反应釜4传感器3个月 → 15.5亿数据点 - Velocity（高速） - 毫秒级处理，异常信号转瞬即逝 - Variety（多样） - 振动波形/温度读数/电流频谱/文本/图像/表单 - Value（价值密度低但挖掘价值大） - 15.5亿数据点中仅几百个异常点对应关键信息 ### 4V对技术选型的影响 - Volume+Velocity → 轮询式协议（Modbus）无法应对 → 需要发布-订阅 - Variety → 需要灵活的消息分类路由 - Value → 数据必须可靠传输 ### 工业大数据分析四层次 - 描述性分析：发生了什么 → 仪表盘 - 诊断性分析：为什么发生 → 根因分析 - 预测性分析：将要发生什么 → 故障预测 - 指导性分析：应该怎么做 → 优化建议 ### 工业大数据应用场景 - 预测性维护 - 质量优化 - 能耗管理 - 生产调度优化 - 产品追溯 ### 数据驱动决策 - 从经验驱动到数据驱动 - 决策更科学准确 ### 时序数据特点 - 趋势性 - 周期性 - 异常点 ## 7.2 MQTT：为数据洪流设计的通信协议 ### MQTT的诞生 - 1999年IBM工程师发明 - 为通过卫星链路监控输油管道传感器 - 协议头部最小仅2字节 - OASIS标准化（v3.1.1 → v5.0） ### 发布-订阅模式 - 发布者 → Broker → 订阅者 - 一次发布，多方订阅 - 设备可主动上报，不需等待轮询 ### 四个核心概念 - Broker（消息代理中枢） - 如Mosquitto - Topic（主题） - 斜杠分层命名 - 通配符：#（多层）/ +（单层） - QoS（服务质量） - QoS 0：最多一次 - QoS 1：至少一次 - QoS 2：恰好一次 - 发布-订阅完全解耦 - 三者生命周期独立 - 无需知道对方存在 ### 两个实用机制 - 保留消息（Retained Message） - 新订阅者上线立即获取最新值 - 遗嘱消息（LWT） - 发布者异常断开时Broker自动通知订阅者 ### MQTT vs Modbus 关键差异 - 请求-应答 vs 发布-订阅 - 不能主动上报 vs 随时发布 - 点对点 vs 天然一对多 - 紧耦合 vs 完全解耦 - 适合车间内通信 vs 适合设备上云和跨系统分发 ## 7.3 动手实践：MQTT Broker与命令行初体验 ### 实践任务 - 安装Mosquitto - Broker + mosquitto-clients - 两个终端发布-订阅测试 - mosquitto_sub订阅 - mosquitto_pub发布 - 消息实时推送 ## 7.4 动手实践：Node-RED MQTT采集→Dashboard可视化 ### 实践任务 - 搭建三个MQTT传感器发布者 - Inject + Function + mqtt out - 三个不同Topic - Dashboard订阅显示三个Gauge仪表盘 - 添加Chart趋势图和Notification告警通知 - 感受发布者和订阅者的完全解耦 - 禁用/启用订阅Flow - 发布者继续发布不受影响 - 重新订阅后立即收到新消息 ## 🎯 课程思政 - 数据有主，使用有界——工业大数据的法律红线 - 《数据安全法》（2021年9月1日施行） - 数据分类分级保护制度 - 核心数据（关系国家安全）→ 严格保护 - 重要数据（可能危害国家安全/公共利益）→ 重点保护 - 一般数据 → 常规保护 - 工业数据同样适用此分类 - 上传数据需做合规判断 - 涉及客户信息需脱敏 - 境外平台需额外考虑数据出境安全',-1)])])}const T=t(i,[["render",d]]);export{p as __pageData,T as default};
